  isWithinBytes,
  parseJson,
} from './saved-format.ts';
import type { GameState } from './game.ts';

export const REPLAY_VERSION = 1;
export const REPLAY_MAX_BYTES = 1_048_576;
export const REPLAY_MAX_ACTIONS = 10_000;
const REPLAY_KEYS = ['version', 'boardCode', 'actions', 'endMs'];
const ACTION_KEYS = ['atMs', 'index'];

export const ReplayProblem = {
  tooLarge: 'tooLarge',
  malformedJson: 'malformedJson',
  format: 'format',
  boardCode: 'boardCode',
  actions: 'actions',
  endTime: 'endTime',
  action: 'action',
  order: 'order',
  index: 'index',
} as const;
export type ReplayProblemKind = (typeof ReplayProblem)[keyof typeof ReplayProblem];
type ReplayResult =
  { readonly state: GameState } | { readonly problem: ReplayProblemKind; readonly action?: number };

export function readReplay(text: string): ReplayResult {
  if (!isWithinBytes(text, REPLAY_MAX_BYTES)) return { problem: ReplayProblem.tooLarge };
  const value = parseJson(text);
  if (value === undefined) return { problem: ReplayProblem.malformedJson };
  if (!isJsonObject(value) || !hasExactKeys(value, REPLAY_KEYS) || value.version !== REPLAY_VERSION)
    return { problem: ReplayProblem.format };
  if (typeof value.boardCode !== 'string' || !parseBoardCode(value.boardCode))
    return { problem: ReplayProblem.boardCode };
  if (!Array.isArray(value.actions) || value.actions.length > REPLAY_MAX_ACTIONS)
    return { problem: ReplayProblem.actions };
  if (!isNonnegativeSafeInteger(value.endMs)) return { problem: ReplayProblem.endTime };
  let state = createGame(value.boardCode);
  let previousTime = 0;
  for (const [position, action] of value.actions.entries()) {
    if (
      !isJsonObject(action) ||
      !hasExactKeys(action, ACTION_KEYS) ||
      !isNonnegativeSafeInteger(action.atMs) ||
      !isNonnegativeSafeInteger(action.index)
    )
      return { problem: ReplayProblem.action, action: position };
    if (action.atMs < previousTime || action.atMs > value.endMs)
      return { problem: ReplayProblem.order, action: position };
    if (action.index >= state.deck.length)
      return { problem: ReplayProblem.index, action: position };
    state = activateCard(advanceGame(state, action.atMs - previousTime), action.index);
    previousTime = action.atMs;
  }
  return { state: advanceGame(state, value.endMs - previousTime) };
}

export function replayGame(text: string): GameState | null {
  const result = readReplay(text);
  return 'state' in result ? result.state : null;
}
import { readFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import {
  readReplay,
  REPLAY_MAX_ACTIONS,
  REPLAY_MAX_BYTES,
  REPLAY_VERSION,
  ReplayProblem,
} from '../src/game/replay.ts';
import { encodeSnapshot } from '../src/game/snapshot.ts';
import type { ReplayProblemKind } from '../src/game/replay.ts';

export const ReplayExit = { success: 0, failure: 1 } as const;
const MISSING_FILE = 'ENOENT';
const PROBLEMS = {
  [ReplayProblem.tooLarge]: `the file is larger than ${REPLAY_MAX_BYTES} bytes`,
  [ReplayProblem.malformedJson]: 'the file is not valid JSON',
  [ReplayProblem.format]: `it isn't a version ${REPLAY_VERSION} replay with exactly version, boardCode, actions and endMs`,
  [ReplayProblem.boardCode]: 'its board code is invalid',
  [ReplayProblem.actions]: `actions must be a list of at most ${REPLAY_MAX_ACTIONS}`,
  [ReplayProblem.endTime]: 'endMs must be a nonnegative safe integer',
  [ReplayProblem.action]: 'needs exactly atMs and index as nonnegative safe integers',
  [ReplayProblem.order]: 'comes before the previous action or after endMs',
  [ReplayProblem.index]: 'names a card outside the board',
} satisfies Record<ReplayProblemKind, string>;

function fail(file: string, reason: string): number {
  process.stderr.write(`Could not replay ${file}: ${reason}.\n`);
  return ReplayExit.failure;
}

function isMissing(error: unknown): boolean {
  return error instanceof Error && 'code' in error && error.code === MISSING_FILE;
}

// npm runs scripts from the package folder and records the caller's folder in INIT_CWD.
export async function runReplay(
  args: readonly string[],
  callerFolder = process.env.INIT_CWD ?? process.cwd(),
): Promise<number> {
  const [file] = args;
  if (!file || args.length !== 1) {
    process.stderr.write('Usage: npm run --silent replay -- PATH\n');
    return ReplayExit.failure;
  }
  let text: string;
  try {
    text = await readFile(resolve(callerFolder, file), 'utf8');
  } catch (error) {
    return fail(file, isMissing(error) ? 'the file does not exist' : "the file can't be read");
  }
  const result = readReplay(text);
  if ('state' in result) {
    process.stdout.write(`${encodeSnapshot(result.state)}\n`);
    return ReplayExit.success;
  }
  const reason = PROBLEMS[result.problem];
  return fail(file, result.action === undefined ? reason : `action ${result.action + 1} ${reason}`);
}
